        "injection.js": { js: options?.injectionSource ?? INJECTION_BUNDLE_SOURCE },
        "recipe.js": { js: recipeSource },
      },
      limits: { cpuMs: env.recipeCpuMs },
      globalOutbound: null,
    });
  } catch (error) {
