export default {
  async fetch(req: Request, env: any): Promise<Response> {
    const url = new URL(req.url);
    if (req.method === "POST" && url.pathname === "/items") {
      const id = crypto.randomUUID();
      await env.DB.prepare("INSERT INTO items (id,status,updated_at) VALUES (?,?,?)").bind(id, "queued", new Date().toISOString()).run();
      const inst = await env.ITEM.create({ id, params: { id } });
      return Response.json({ id, instance: inst.id });
    }
    const m = url.pathname.match(/^\/items\/([^/]+)(\/object)?$/);
    if (m) {
      if (m[2]) {
        const o = await env.BUCKET.get(`items/${m[1]}.txt`);
        return o ? new Response(o.body) : new Response("no object", { status: 404 });
      }
      const row = await env.DB.prepare("SELECT * FROM items WHERE id=?").bind(m[1]).first();
      return Response.json(row);
    }
    return new Response("api ok");
  },
};
E
