import { WorkflowEntrypoint, WorkflowStep, WorkflowEvent } from "cloudflare:workers";
import { DurableObject } from "cloudflare:workers";

export class DomainQueue extends DurableObject {
  async lease(): Promise<number> {
    const n = ((await this.ctx.storage.get<number>("n")) ?? 0) + 1;
    await this.ctx.storage.put("n", n);
    return n;
  }
}

const RUNTIME = `export default { fetch(){ return Response.json({ok:true, sum: [1,2,3].reduce((a,b)=>a+b)}) } }`;

export class ItemWorkflow extends WorkflowEntrypoint<any, { id: string }> {
  async run(event: WorkflowEvent<{ id: string }>, step: WorkflowStep) {
    const { id } = event.payload;
    const set = (status: string, detail?: string) =>
      this.env.DB.prepare("UPDATE items SET status=?, detail=COALESCE(?,detail), updated_at=? WHERE id=?").bind(status, detail ?? null, new Date().toISOString(), id).run();

    await step.do("fetch", async () => { await set("fetching"); });
    const n = await step.do("lease", async () => {
      const stub = this.env.DOMAIN_QUEUE.get(this.env.DOMAIN_QUEUE.idFromName("example.com"));
      const n = await stub.lease();
      await set("leased", `lease #${n}`);
      return n;
    });
    await step.sleep("pause", "2 seconds");
    const sandbox = await step.do("sandbox", async () => {
      const w = this.env.LOADER.load({ compatibilityDate: "2026-09-01", mainModule: "r.js", modules: { "r.js": { js: RUNTIME } }, globalOutbound: null });
      const r = await w.getEntrypoint().fetch(new Request("https://x/"));
      const j = await r.json();
      await set("sandboxed", JSON.stringify(j));
      return j;
    });
    await step.do("store", async () => {
      await this.env.BUCKET.put(`items/${id}.txt`, `hello from workflow, lease ${n}`);
      await set("ready", "stored r2");
    });
    return sandbox;
  }
}

export default { fetch: () => new Response("pipeline ok") };
